<?php
declare(strict_types=1);require dirname(__DIR__).'/src/bootstrap.php';$method=$_SERVER['REQUEST_METHOD']??'GET';$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
if($path==='/'||!str_starts_with($path,'/api/')){require __DIR__.'/site.php';exit;}
if($path==='/api/v1/health')out(200,['ok'=>true,'service'=>'DCP Cloud','mode'=>'signaling-only','relay'=>false]);
if($path==='/api/v1/devices/register'&&$method==='POST'){$b=body();$id=uuid4();$token=bin2hex(random_bytes(32));$s=$db->prepare('INSERT INTO devices(id,label,platform,credential_hash,last_seen_at) VALUES(?,?,?,?,NOW())');$s->execute([$id,substr(trim((string)($b['label']??'DCP Device')),0,120),substr((string)($b['platform']??'unknown'),0,40),secret_hash($token)]);out(201,['device_id'=>$id,'device_token'=>$token,'heartbeat_seconds'=>30]);}
if($path==='/api/v1/devices/heartbeat'&&$method==='POST'){$d=auth_device($db);out(200,['ok'=>true,'device_id'=>$d['id'],'server_time'=>gmdate('c')]);}
if($path==='/api/v1/devices'&&$method==='GET'){$d=auth_device($db);$s=$db->prepare('SELECT id,label,platform,last_seen_at,IF(last_seen_at>DATE_SUB(NOW(),INTERVAL 90 SECOND),1,0) online FROM devices WHERE user_id <=> ? AND id<>? AND revoked_at IS NULL ORDER BY label');$s->execute([$d['user_id'],$d['id']]);out(200,['devices'=>$s->fetchAll()]);}
if($path==='/api/v1/connections/request'&&$method==='POST'){$d=auth_device($db);$b=body();$target=(string)($b['target_device']??'');$q=$db->prepare('SELECT id FROM devices WHERE id=? AND revoked_at IS NULL');$q->execute([$target]);if(!$q->fetch())out(404,['error'=>'target_not_found']);$id=uuid4();$db->prepare("INSERT INTO connection_requests(id,source_device,target_device,status,expires_at) VALUES(?,?,?,'pending',DATE_ADD(NOW(),INTERVAL 90 SECOND))")->execute([$id,$d['id'],$target]);out(201,['request_id'=>$id,'status'=>'pending']);}
if(preg_match('#^/api/v1/connections/([a-f0-9-]{36})/signal$#',$path,$m)&&$method==='POST'){$d=auth_device($db);$b=body();$payload=(string)($b['envelope']??'');if($payload===''||strlen($payload)>32768)out(422,['error'=>'invalid_envelope']);$q=$db->prepare('SELECT source_device,target_device FROM connection_requests WHERE id=? AND expires_at>NOW()');$q->execute([$m[1]]);$c=$q->fetch();if(!$c||!in_array($d['id'],[$c['source_device'],$c['target_device']],true))out(404,['error'=>'request_not_found']);$to=$d['id']===$c['source_device']?$c['target_device']:$c['source_device'];$db->prepare('INSERT INTO signaling_messages(request_id,sender_device,recipient_device,envelope,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 180 SECOND))')->execute([$m[1],$d['id'],$to,$payload]);out(202,['accepted'=>true,'delivery'=>'signaling_only']);}
if(preg_match('#^/api/v1/connections/([a-f0-9-]{36})/signals$#',$path,$m)&&$method==='GET'){$d=auth_device($db);$after=max(0,(int)($_GET['after']??0));$s=$db->prepare('SELECT id,sender_device,envelope,created_at FROM signaling_messages WHERE request_id=? AND recipient_device=? AND id>? AND expires_at>NOW() ORDER BY id LIMIT 50');$s->execute([$m[1],$d['id'],$after]);out(200,['signals'=>$s->fetchAll()]);}
out(404,['error'=>'not_found']);
